#include <stdio.h>

struct Ponto {
    int x;
    int y;
};

void oClonador(int x, int y) {
    struct Ponto original;
    original.x = x;
    original.y = y;
    struct Ponto copia;
    copia = original;
    original.x = original.x + 100;
    printf("original %d %d\n", original.x, original.y);
    printf("copia %d %d\n", copia.x, copia.y);
}
